// ۱. تعریف کلاس (پیش‌نیاز)
کلاس ماشین_حساب {
    عدد ضریب;
    تابع ضرب_کن(عدد مقدار) -> عدد {
        برگردان این.ضریب * مقدار;
    }
}

// ۲. ساخت شیء و دسترسی به اعضا
ماشین_حساب حسابگر = ماشین_حساب();
حسابگر.ضریب = 10;
چاپ(حسابگر.ضرب_کن(5));   // خروجی: 50

حسابگر.ضریب = 20;
چاپ(حسابگر.ضرب_کن(3));   // خروجی: 60

