// 1. Class definition (Prerequisite)
class Calculator {
    int factor;
    func multiply(int value) -> int {
        return this.factor * value;
    }
}

// 2. Object creation and member access
Calculator calc = Calculator();
calc.factor = 10;
print(calc.multiply(5));   // Output: 50

calc.factor = 20;
print(calc.multiply(3));   // Output: 60

