// 1. クラス定義（前提条件）
クラス 電卓 {
    整数 係数;
    関数 掛ける(整数 値) -> 整数 {
        返す 自身.係数 * 値;
    }
}

// 2. オブジェクト生成とメンバーアクセス
電卓 電卓_インスタンス = 電卓();
電卓_インスタンス.係数 = 10;
表示(電卓_インスタンス.掛ける(5));   // 出力: 50

電卓_インスタンス.係数 = 20;
表示(電卓_インスタンス.掛ける(3));   // 出力: 60

