// 1. Определение класса (Предварительное условие)
класс Калькулятор {
    цел множитель;
    функ умножить(цел значение) -> цел {
        возврат это.множитель * значение;
    }
}

// 2. Создание объекта и доступ к членам
Калькулятор калькулятор_объект = Калькулятор();
калькулятор_объект.множитель = 10;
печать(калькулятор_объект.умножить(5));   // Вывод: 50

калькулятор_объект.множитель = 20;
печать(калькулятор_объект.умножить(3));   // Вывод: 60
